// === Tab: mySketch ===
pins=[]
pins_num=150

setup=()=> {
  createCanvas(windowWidth, windowHeight)
  y=0
  for (i=0; i<pins_num; i++ ) {
    pins[i]=createVector(random(width), random(height))
  }
}

draw=()=> {
  if (y<height) {
    for (x=0; x<width; x++ ) {
      angle=0
      pins.forEach(p=>angle+=atan2(p.y-y, p.x-x))
      colour=map(sin(angle), -1, 1, 0, 256)
      stroke(colour)
      line(x, y, x, y+colour)
    }
    y++
  }
}

mousePressed=()=>setup()
